// pages/products.js
import { useRouter } from 'next/router';

export default function Products() {
  const router = useRouter();
  const { category, sort } = router.query;

  const applySort = (sortValue) => {
    router.push({
      pathname: '/products',
      query: { ...router.query, sort: sortValue },
    }, undefined, { shallow: true });
  };

  return (
    <div>
      <p>Category: {category || 'All'}, Sort: {sort || 'none'}</p>
      <button onClick={() => applySort('price')}>Sort by Price</button>
    </div>
  );
}
